tool_input.command:
cat > "C:/Users/VM Oct26/AppData/Local/Temp/claude/C--claudecode-dark-raiders/5724ca72-2714-4df0-b4bf-9ca12ddbe60b/scratchpad/mk-cw-expgrp.ps1" <<'EOF'
$g=[IO.File]::ReadAllText($(if($env:MK_SRC){$env:MK_SRC}else{'C:\claudecode\dark raiders\dark_raiders.html'}))
function L([string]$rx){ $m=[regex]::Matches($g,$rx); if($m.Count -ne 1){ throw "anchor $rx matched $($m.Count)" }; return $m[0].Value.Replace("`r",'') }
$a1=L "#root #settingsmodal\.expmode #setlist \.expgroup\{[^}]*\}"
$r1="/* v33.31 (cw-expgrp) critic 61 rounds 1 to 2 (score 2): the four group names never showed because cw-setsechd zeroes every opacity:.7 row with !important. Scoped back on for the experimental page: 48px band, 16px name. */`n#root #settingsmodal.expmode #setlist .expgroup{ height:48px !important; min-height:48px !important; margin:0 !important; padding:16px var(--sp-3) 8px !important; border:0 !important; background:transparent; box-shadow:none; opacity:1 !important; overflow:visible !important; }"
$chk=@'
  {v:'VER',what:'the four experimental group names show with a real height on the experimental page',
   run:function(){
     var bad=[], modal=document.getElementById('settingsmodal'), list=document.getElementById('setlist'), oldCls, oldSub=SETSUB, gs, i, r;
     if(!modal||!list||typeof renderSettings!=='function') return 'SKIP: no settings page';
     try{
       __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       oldCls=modal.className; modal.classList.add('on'); SETSUB='exp'; renderSettings();
       gs=list.querySelectorAll('[data-exp-group]');
       if(gs.length!==4) return 'expected four group rows, found '+gs.length;
       for(i=0;i<gs.length;i++){
         r=gs[i].getBoundingClientRect();
         if(r.height<40) bad.push('group '+gs[i].getAttribute('data-exp-group')+' is '+Math.round(r.height)+'px tall');
         if(parseFloat(getComputedStyle(gs[i].querySelector('b')).fontSize)<14) bad.push('group name under 14px');
       }
       return bad.length?bad.join('; '):null;
     } finally { SETSUB=oldSub; try{ renderSettings(); }catch(_e){} modal.className=oldCls; }
   }},
'@.Replace("`r",'')
$d=[ordered]@{
  title='EXPERIMENTAL GROUP NAMES SHOW'
  why='The experimental page has four groups (raid, combat, events, extras) but their names were squeezed to zero height by an older Settings rule. The critic scored the page 2 for it. Now each group has a 48px band with its name.'
  now='The experimental page shows raid, combat, events and extras headings.'
  edits=@( [ordered]@{ anchor=$a1; replacement=$r1 } )
  check=$chk
}
[IO.File]::WriteAllText('C:\claudecode\dark raiders\tools\handoff\drafts\draft-cw-expgrp.json',($d | ConvertTo-Json -Depth 6),(New-Object Text.UTF8Encoding $false))
'written'
EOF
echo ok

